problems.solution:
def column(M, j):
    return [row[j] for row in M]


def matvec(M, v):
    if len(v) != len(M[0]):
        raise ValueError("vector length must equal the number of columns")
    result = [0] * len(M)
    for j in range(len(v)):
        for i in range(len(M)):
            result[i] += v[j] * M[i][j]
    return result


def matmul(A, B):
    if len(A[0]) != len(B):
        raise ValueError("columns of A must equal rows of B")
    cols = [matvec(A, column(B, j)) for j in range(len(B[0]))]
    return [[cols[j][i] for j in range(len(cols))] for i in range(len(A))]

import numpy as np

def commutes(A, B):
    return bool(np.allclose(A @ B, B @ A))


def assoc_holds(A, B, C):
    return bool(np.allclose((A @ B) @ C, A @ (B @ C)))


def collapse(layers):
    M = np.eye(layers[0].shape[1])
    for W in layers:
        M = W @ M
    return M
